import requests
import json


class BaseSession(object):
    PROTOCOL = 'https://'

    def __init__(self, ncir_address, verify):
        self.auth_token = None
        self._ncir_address = ncir_address
        self._verify = verify

    def send_request(self, method, endpoint, port, headers=None, **options):
        if headers is None:
            headers = {}
        method = getattr(requests, method.lower())
        url = '{protocol}{address}:{port}/{endpoint}'.format(protocol=self.PROTOCOL, address=self._ncir_address,
                                                             port=port, endpoint=endpoint)
        self._create_header(headers)
        options.update({'headers': headers, 'verify': self._verify})
        return method(url=url, **options)

    def _create_header(self, headers):
        return headers


class Session17A(BaseSession):
    TOKEN_ENDPOINT = 'v3/auth/tokens'
    TOKEN_PORT = '5000'

    def __init__(self, ncir_address, verify):
        super(Session17A, self).__init__(ncir_address, verify)

    def authenticate(self, username, password):
        headers = {'Content-Type': 'application/json'}
        body = {"auth": {
            "identity": {
                "methods": ["password"],
                "password": {
                    "user": {
                        "name": username,
                        "domain": {"id": "default"},
                        "password": password
                    }
                }
            }
        }}
        return self.send_request('post', self.TOKEN_ENDPOINT, self.TOKEN_PORT, headers, data=json.dumps(body))

    def _create_header(self, headers):
        headers.update({'X-Auth-Token': self.auth_token})
        return headers
